using UnityEngine;
namespace NoiteSemFim {
public static class UISkin {
 static Texture2D atlas,background;static Rect[] cells;static bool loaded;
 public static Texture2D Background=>background??(background=Resources.Load<Texture2D>("Art/menu-principal-v4")??Resources.Load<Texture2D>("Art/menu-v2"));
 static void Load(){if(loaded)return;atlas=Resources.Load<Texture2D>("Art/ui-v2");if(atlas==null)return;loaded=true;cells=new Rect[16];int w=atlas.width/4,h=atlas.height/4;var pixels=atlas.GetPixels32();for(int i=0;i<16;i++){int sx=(i%4)*w,sy=atlas.height-(i/4+1)*h;int cw=w,ch=h;if(i==12){cw=(int)(atlas.width*.224f);ch=(int)(atlas.height*.30f);}if(i==13){sx=(int)(atlas.width*.226f);cw=(int)(atlas.width*.368f);}if(i==14){sx=(int)(atlas.width*.598f);cw=(int)(atlas.width*.196f);}if(i==15){sx=(int)(atlas.width*.796f);cw=atlas.width-sx;}int minX=cw,minY=ch,maxX=0,maxY=0;for(int y=0;y<ch;y++)for(int x=0;x<cw;x++)if(pixels[(sy+y)*atlas.width+sx+x].a>40){minX=Mathf.Min(minX,x);minY=Mathf.Min(minY,y);maxX=Mathf.Max(maxX,x);maxY=Mathf.Max(maxY,y);}cells[i]=minX>maxX?new Rect(sx,sy,w,h):new Rect(sx+minX,sy+minY,maxX-minX+1,maxY-minY+1);}}
 public static bool Draw(int id,Rect target,bool sliced=true){Load();if(atlas==null)return false;Rect src=cells[Mathf.Clamp(id,0,15)];if(!sliced){Part(target,src);return true;}float border=Mathf.Min(src.width,src.height)*.18f;float dest=Mathf.Min(Mathf.Min(target.width,target.height)*.28f,20);float[] xs={target.x,target.x+dest,target.xMax-dest,target.xMax};float[] ys={target.y,target.y+dest,target.yMax-dest,target.yMax};float[] us={src.x,src.x+border,src.xMax-border,src.xMax};float[] vs={src.yMax,src.yMax-border,src.y+border,src.y};for(int y=0;y<3;y++)for(int x=0;x<3;x++){Rect d=new Rect(xs[x],ys[y],xs[x+1]-xs[x],ys[y+1]-ys[y]);Rect r=new Rect(us[x],vs[y+1],us[x+1]-us[x],vs[y]-vs[y+1]);if(x==1&&(y==0||y==2)){float sc=r.width*.3f,dc=Mathf.Min(d.width*.7f,sc*dest/border);float sl=(r.width-sc)*.5f,dl=(d.width-dc)*.5f;Part(new Rect(d.x,d.y,dl,d.height),new Rect(r.x,r.y,sl,r.height));Part(new Rect(d.x+dl,d.y,dc,d.height),new Rect(r.x+sl,r.y,sc,r.height));Part(new Rect(d.x+dl+dc,d.y,dl,d.height),new Rect(r.x+sl+sc,r.y,sl,r.height));}else Part(d,r);}return true;}
 static void Part(Rect target,Rect source){GUI.DrawTextureWithTexCoords(target,atlas,new Rect(source.x/atlas.width,source.y/atlas.height,source.width/atlas.width,source.height/atlas.height),true);}
}
}
